-- Run after migration text without its COMMIT. All test fixtures roll back.
do $$
declare e uuid:=gen_random_uuid();w uuid:=gen_random_uuid();x uuid:=gen_random_uuid();ad uuid:=gen_random_uuid();j uuid:=gen_random_uuid();a uuid:=gen_random_uuid();assignment uuid;d uuid;s uuid;n int;
begin
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 insert into auth.users(id,email,raw_user_meta_data) values(e,e||'@cases.invalid','{"account_type":"employer"}'),(w,w||'@cases.invalid','{}'),(x,x||'@cases.invalid','{}'),(ad,ad||'@cases.invalid','{}');
 update public.profiles set role='admin' where id=ad;
 update public.profiles set employer_premium_until=now()+interval '1 day' where id=e;
 perform set_config('request.jwt.claims',json_build_object('sub',e,'role','authenticated')::text,true);set local role authenticated;
 insert into public.jobs(id,employer_id,title,description,category,status,submission_key) values(j,e,'Work dispute fixture','Temporary job for case permission tests.','Development','published',gen_random_uuid());reset role;
 insert into public.applications(id,job_id,applicant_id,cover_note) values(a,j,w,'Temporary application for private case validation');set local role authenticated;
 assignment:=public.assign_job_worker(a);
 d:=public.open_work_dispute(assignment,'no_show','The assigned worker did not arrive at the agreed time.','https://example.com/test-evidence');
 begin perform public.open_work_dispute(assignment,'other','A second case for the same work should be rejected.','');raise exception 'Duplicate report permitted';exception when raise_exception then if sqlerrm<>'A case already exists; reply there' then raise;end if;end;
 if public.account_is_suspended(w) then raise exception 'Report automatically suspended worker';end if;
 perform set_config('request.jwt.claims',json_build_object('sub',x,'role','authenticated')::text,true);
 select count(*) into n from public.work_disputes where id=d;if n<>0 then raise exception 'Outsider read case';end if;
 select count(*) into n from public.work_dispute_messages where dispute_id=d;if n<>0 then raise exception 'Outsider read evidence';end if;
 begin perform public.open_work_dispute(assignment,'other','I am not a participant and cannot open this case.','');raise exception 'Unrelated report permitted';exception when raise_exception then if sqlerrm<>'Work case unavailable' then raise;end if;end;
 begin perform public.suspend_case_account(d,w,7,'Unauthorized restriction attempt');raise exception 'Nonadmin suspended';exception when raise_exception then if sqlerrm<>'Admin required' then raise;end if;end;
 perform set_config('request.jwt.claims',json_build_object('sub',w,'role','authenticated')::text,true);
 perform public.reply_work_dispute(d,'I disagree and would like to explain the delay.','');
 perform set_config('request.jwt.claims',json_build_object('sub',ad,'role','authenticated')::text,true);
 begin perform public.suspend_case_account(d,w,7,'No recorded review yet');raise exception 'Unreviewed suspension permitted';exception when raise_exception then if sqlerrm<>'Review the case before restricting an account' then raise;end if;end;
 perform public.review_work_dispute(d,'reviewing','Both statements reviewed. Temporary restriction test only.');
 s:=public.suspend_case_account(d,w,7,'Test restriction after reviewing statements');
 perform set_config('request.jwt.claims',json_build_object('sub',w,'role','authenticated')::text,true);
 if not public.account_is_suspended(w) then raise exception 'Restriction missing';end if;
 begin perform public.update_job_work(assignment,'cancel');raise exception 'Suspended marketplace action permitted';exception when raise_exception then if sqlerrm not like 'Marketplace access suspended%' then raise;end if;end;
 perform public.reply_work_dispute(d,'Please review my appeal and evidence.','');
 perform public.create_support_ticket('Appeal test','Account','Please review the temporary restriction.');
 select count(*) into n from public.account_suspensions where id=s;if n<>1 then raise exception 'Owner cannot see restriction';end if;
 perform set_config('request.jwt.claims',json_build_object('sub',e,'role','authenticated')::text,true);
 select count(*) into n from public.account_suspensions where id=s;if n<>0 then raise exception 'Other participant read restriction detail';end if;
 perform set_config('request.jwt.claims',json_build_object('sub',ad,'role','authenticated')::text,true);
 perform public.restore_case_account(s,'Test appeal reviewed and access restored');
 if public.account_is_suspended(w) then raise exception 'Restore failed';end if;
 s:=public.suspend_case_account(d,e,1,'Test hirer suspension uses the same rules');
 reset role;perform set_config('request.jwt.claims','{}',true);set local role anon;
 select count(*) into n from public.jobs where id=j;if n<>0 then raise exception 'Suspended hirer listing remains public';end if;
 reset role;perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 update public.account_suspensions set starts_at=now()-interval '2 days',ends_at=now()-interval '1 day' where id=s;
 if public.account_is_suspended(e) then raise exception 'Expired restriction still active';end if;
 perform set_config('request.jwt.claims','{}',true);set local role anon;
 select count(*) into n from public.jobs where id=j;if n<>1 then raise exception 'Expired restriction did not restore listing';end if;
 reset role;
end$$;
rollback;
select 'PASS: private cases and evidence, participant-only reports, duplicate prevention, no automatic suspension, admin review required, suspended writes blocked, replies and appeals retained, private restriction history, restoration and automatic expiry; fixtures rolled back' as result;
